"""In-memory stand-ins for the Supabase and Gemini clients.

The fakes cover only what the routers call. A method the routers do not use
is missing on purpose, so a test that reaches it fails loudly instead of
quietly doing the wrong thing.
"""

import copy
import itertools
from types import SimpleNamespace

# Tables whose primary key is supplied by the caller (a user id) rather than
# generated by the database. Every other table gets an integer `id` on insert
# when the row does not carry one, like the identity columns in production.
TABLES_WITHOUT_IDENTITY = {"users", "user_streaks"}


class FakeAuthError(Exception):
    """Raised by the fake auth client for a token it did not issue."""


class FakeResponse:
    def __init__(self, data):
        self.data = data
        self.count = None


class FakeQuery:
    """One `supabase.table(name)` chain: an operation, filters, order, limit."""

    def __init__(self, db, table):
        self._db = db
        self._table = table
        self._operation = "select"
        self._columns = ["*"]
        self._payload = None
        self._filters = []
        self._orders = []
        self._limit = None

    def select(self, columns="*"):
        self._operation = "select"
        self._columns = [c.strip() for c in columns.split(",") if c.strip()]
        return self

    def insert(self, rows):
        self._operation = "insert"
        self._payload = rows
        return self

    def update(self, values):
        self._operation = "update"
        self._payload = values
        return self

    def delete(self):
        self._operation = "delete"
        return self

    def eq(self, column, value):
        self._filters.append(lambda row: row.get(column) == value)
        return self

    def in_(self, column, values):
        values = list(values)
        self._filters.append(lambda row: row.get(column) in values)
        return self

    def order(self, column, *, desc=False):
        self._orders.append((column, desc))
        return self

    def limit(self, size):
        self._limit = size
        return self

    def execute(self):
        rows = self._db.tables.setdefault(self._table, [])
        if self._operation == "insert":
            return FakeResponse(self._db._insert(self._table, self._payload))

        matched = [row for row in rows if all(f(row) for f in self._filters)]

        if self._operation == "update":
            for row in matched:
                row.update(copy.deepcopy(self._payload))
            return FakeResponse(copy.deepcopy(matched))

        if self._operation == "delete":
            deleted = {id(row) for row in matched}
            self._db.tables[self._table] = [row for row in rows if id(row) not in deleted]
            return FakeResponse(copy.deepcopy(matched))

        # Later .order() calls break ties of earlier ones, so sort from the
        # last one back. Postgres puts NULLs last ascending, first descending.
        for column, desc in reversed(self._orders):
            present = [r for r in matched if r.get(column) is not None]
            missing = [r for r in matched if r.get(column) is None]
            present.sort(key=lambda r: r[column], reverse=desc)
            matched = missing + present if desc else present + missing
        if self._limit is not None:
            matched = matched[: self._limit]
        if self._columns != ["*"]:
            matched = [{c: row.get(c) for c in self._columns} for row in matched]
        return FakeResponse(copy.deepcopy(matched))


class FakeRpc:
    def __init__(self, db, name, params):
        self._db = db
        self._name = name
        self._params = params

    def execute(self):
        self._db.rpc_calls.append((self._name, copy.deepcopy(self._params)))
        handler = self._db.rpc_handlers.get(self._name)
        return FakeResponse(handler(self._params) if handler else None)


class FakeAuth:
    def __init__(self):
        self._users_by_token = {}

    def token_for(self, user_id):
        """Return a bearer token that `get_user` resolves to `user_id`."""
        token = f"test-token-{user_id}"
        self._users_by_token[token] = user_id
        return token

    def get_user(self, jwt=None):
        if jwt not in self._users_by_token:
            raise FakeAuthError("invalid JWT: token was not issued by the fake")
        return SimpleNamespace(user=SimpleNamespace(id=self._users_by_token[jwt]))


class FakeSupabase:
    """Replaces the shared client from `supabase_client.py` in tests."""

    def __init__(self):
        self.tables = {}
        self.rpc_calls = []
        self.rpc_handlers = {}
        self.auth = FakeAuth()
        self._ids = itertools.count(1)

    def table(self, name):
        return FakeQuery(self, name)

    def rpc(self, name, params=None):
        return FakeRpc(self, name, params or {})

    def seed(self, table, rows):
        """Insert rows directly and return them as stored, ids included."""
        return self._insert(table, rows)

    def rows(self, table):
        """A copy of everything currently stored in `table`."""
        return copy.deepcopy(self.tables.get(table, []))

    def _insert(self, table, rows):
        rows = [rows] if isinstance(rows, dict) else list(rows)
        stored = []
        for row in rows:
            row = copy.deepcopy(row)
            if table not in TABLES_WITHOUT_IDENTITY and "id" not in row:
                row["id"] = next(self._ids)
            self.tables.setdefault(table, []).append(row)
            stored.append(row)
        return copy.deepcopy(stored)


class FakeModels:
    def __init__(self):
        self.responses = []
        self.calls = []

    def generate_content(self, *, model, contents, config=None):
        self.calls.append({"model": model, "contents": contents, "config": config})
        if not self.responses:
            raise RuntimeError("fake Gemini: no response queued for generate_content")
        reply = self.responses.pop(0)
        if isinstance(reply, BaseException):
            raise reply
        return SimpleNamespace(text=reply)


class FakeAuthTokens:
    def __init__(self):
        self.calls = []

    def create(self, *, config=None):
        self.calls.append({"config": config})
        return SimpleNamespace(name=f"auth_tokens/fake-{len(self.calls)}")


class FakeGemini:
    """Replaces every `google.genai.Client` the API creates.

    Queue the text of each model reply in `models.responses` (an exception
    instance is raised instead); calls are recorded in `models.calls`.
    """

    def __init__(self):
        self.models = FakeModels()
        self.auth_tokens = FakeAuthTokens()
